import{_ as e,o as t,c as a,Q as o}from"./chunks/framework.5916b37e.js";const f=JSON.parse('{"title":"Module: Controls/cameraTransitions","description":"","frontmatter":{},"headers":[],"relativePath":"apidist/modules/Controls_cameraTransitions.md","filePath":"apidist/modules/Controls_cameraTransitions.md"}'),r={name:"apidist/modules/Controls_cameraTransitions.md"},n=o('<p><a href="./../README.html">copper3d</a> / <a href="./../modules.html">Modules</a> / Controls/cameraTransitions</p><h1 id="module-controls-cameratransitions" tabindex="-1">Module: Controls/cameraTransitions <a class="header-anchor" href="#module-controls-cameratransitions" aria-label="Permalink to &quot;Module: Controls/cameraTransitions&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of contents&quot;">​</a></h2><h3 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h3><ul><li><a href="./../interfaces/Controls_cameraTransitions.Pose.html">Pose</a></li></ul><h3 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h3><ul><li><a href="./Controls_cameraTransitions.html#easeinoutcubic">easeInOutCubic</a></li><li><a href="./Controls_cameraTransitions.html#interpolateflightpose">interpolateFlightPose</a></li><li><a href="./Controls_cameraTransitions.html#orbitsteppose">orbitStepPose</a></li><li><a href="./Controls_cameraTransitions.html#orbitswingangle">orbitSwingAngle</a></li><li><a href="./Controls_cameraTransitions.html#posedistance">poseDistance</a></li><li><a href="./Controls_cameraTransitions.html#rotatearoundaxis">rotateAroundAxis</a></li><li><a href="./Controls_cameraTransitions.html#viewpointtopose">viewPointToPose</a></li><li><a href="./Controls_cameraTransitions.html#zoompose">zoomPose</a></li></ul><h2 id="functions-1" tabindex="-1">Functions <a class="header-anchor" href="#functions-1" aria-label="Permalink to &quot;Functions&quot;">​</a></h2><h3 id="easeinoutcubic" tabindex="-1">easeInOutCubic <a class="header-anchor" href="#easeinoutcubic" aria-label="Permalink to &quot;easeInOutCubic&quot;">​</a></h3><p>▸ <strong>easeInOutCubic</strong>(<code>t</code>): <code>number</code></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>t</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><h4 id="defined-in" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L26" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:26</a></p><hr><h3 id="interpolateflightpose" tabindex="-1">interpolateFlightPose <a class="header-anchor" href="#interpolateflightpose" aria-label="Permalink to &quot;interpolateFlightPose&quot;">​</a></h3><p>▸ <strong>interpolateFlightPose</strong>(<code>from</code>, <code>to</code>, <code>t</code>): <a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><p>Interpolates a camera between two poses. <code>t</code> is expected already eased -- this has no timing concerns of its own, which is what makes it testable without a clock.</p><p>The pivot lerps from one target to the other, and the camera&#39;s ORIENTATION (both its direction from the pivot and its up vector) is carried by a single rotation built from the two poses&#39; full orthonormal bases -- not by interpolating <code>dir</code> and <code>up</code> independently.</p><p>That is a correctness requirement, not a style choice. Real preset data routinely contains antipodal up vectors on the same view axis (two views of the same volume authored from opposite conventions). A plain <code>lerp(upFrom, upTo, t)</code> passes through the zero vector at t=0.5, where <code>normalize</code> has no correct answer: the camera holds upside-down, then snaps 180 degrees in one frame. Composing the two bases into a relative rotation makes that case a well-defined 180-degree roll about the shared axis -- a smooth roll through the midpoint. The same construction covers two antipodal camera positions about one target.</p><p>Reproduces <code>from.position</code> exactly at t=0 and <code>to.position</code> at t=1. <code>up</code> is likewise exact WHEN each pose&#39;s own <code>up</code> is already perpendicular to its own view direction; one that leans toward the view axis is silently squared up, which is by design -- it is not a meaningful camera roll.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>from</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></td></tr><tr><td style="text-align:left;"><code>to</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></td></tr><tr><td style="text-align:left;"><code>t</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><h4 id="defined-in-1" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-1" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L264" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:264</a></p><hr><h3 id="orbitsteppose" tabindex="-1">orbitStepPose <a class="header-anchor" href="#orbitsteppose" aria-label="Permalink to &quot;orbitStepPose&quot;">​</a></h3><p>▸ <strong>orbitStepPose</strong>(<code>pose</code>, <code>yawRad</code>, <code>pitchRad</code>): <a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><p>Orbits the camera around its own pivot by <code>yawRad</code> about its up vector, then by <code>pitchRad</code> about the RESULTING right vector. The pivot and the orbit radius are both untouched, so a run of steps can never walk the camera away from what it is looking at.</p><p>Pitch about the yawed right vector, not the original: rotating about a stale axis makes a diagonal (left+up) combination drift off the sphere instead of tracing it.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pose</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></td></tr><tr><td style="text-align:left;"><code>yawRad</code></td><td style="text-align:left;"><code>number</code></td></tr><tr><td style="text-align:left;"><code>pitchRad</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><h4 id="defined-in-2" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-2" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L304" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:304</a></p><hr><h3 id="orbitswingangle" tabindex="-1">orbitSwingAngle <a class="header-anchor" href="#orbitswingangle" aria-label="Permalink to &quot;orbitSwingAngle&quot;">​</a></h3><p>▸ <strong>orbitSwingAngle</strong>(<code>t</code>, <code>turns</code>): <code>number</code></p><p>Swing angle for an entrance orbit. <code>turns</code> is a SWING AMPLITUDE, not a net rotation: <code>sin(t*pi)</code> goes out and comes back to zero, so the camera always ends exactly on the framed preset view (t=1 -&gt; angle 0) however large <code>turns</code> is. Do not &quot;fix&quot; this into a net rotation; that ends the intro off-preset.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>t</code></td><td style="text-align:left;"><code>number</code></td></tr><tr><td style="text-align:left;"><code>turns</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><h4 id="defined-in-3" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-3" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L343" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:343</a></p><hr><h3 id="posedistance" tabindex="-1">poseDistance <a class="header-anchor" href="#posedistance" aria-label="Permalink to &quot;poseDistance&quot;">​</a></h3><p>▸ <strong>poseDistance</strong>(<code>pose</code>): <code>number</code></p><p>The camera&#39;s orbit radius: how far <code>pose.position</code> sits from the pivot it looks at. Lets a push-in be expressed as an absolute target distance (idempotent) rather than a repeated fractional step.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pose</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></td></tr></tbody></table><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>number</code></p><h4 id="defined-in-4" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-4" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L290" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:290</a></p><hr><h3 id="rotatearoundaxis" tabindex="-1">rotateAroundAxis <a class="header-anchor" href="#rotatearoundaxis" aria-label="Permalink to &quot;rotateAroundAxis&quot;">​</a></h3><p>▸ <strong>rotateAroundAxis</strong>(<code>v</code>, <code>axis</code>, <code>angleRad</code>): <code>Vec3Tuple</code></p><p>Rodrigues&#39; rotation formula: rotates <code>v</code> by <code>angleRad</code> around <code>axis</code> (which need not be pre-normalized). Unlike slerping between two vectors, this has no degeneracy at any angle including a half turn -- the axis is given, not derived from a dot product between vectors that might be antiparallel.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>v</code></td><td style="text-align:left;"><code>Vec3Tuple</code></td></tr><tr><td style="text-align:left;"><code>axis</code></td><td style="text-align:left;"><code>Vec3Tuple</code></td></tr><tr><td style="text-align:left;"><code>angleRad</code></td><td style="text-align:left;"><code>number</code></td></tr></tbody></table><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>Vec3Tuple</code></p><h4 id="defined-in-5" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-5" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L105" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:105</a></p><hr><h3 id="viewpointtopose" tabindex="-1">viewPointToPose <a class="header-anchor" href="#viewpointtopose" aria-label="Permalink to &quot;viewPointToPose&quot;">​</a></h3><p>▸ <strong>viewPointToPose</strong>(<code>vp</code>): <a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><p>Reads a view preset as a <code>Pose</code>, so a flight&#39;s destination is built from the same data an instant <code>loadView</code> would apply.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th></tr></thead><tbody><tr><td style="text-align:left;"><code>vp</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_orbitFraming.CameraViewPreset.html"><code>CameraViewPreset</code></a></td></tr></tbody></table><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><h4 id="defined-in-6" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-6" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L33" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:33</a></p><hr><h3 id="zoompose" tabindex="-1">zoomPose <a class="header-anchor" href="#zoompose" aria-label="Permalink to &quot;zoomPose&quot;">​</a></h3><p>▸ <strong>zoomPose</strong>(<code>pose</code>, <code>factor</code>, <code>minDistance?</code>): <a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><p>Scales the camera&#39;s distance from its pivot by <code>factor</code> along the unchanged view direction. Clamped at <code>minDistance</code> because a zero radius has no direction to normalize -- a held zoom-in key would otherwise collapse the pose into NaN one frame after reaching the pivot.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table><thead><tr><th style="text-align:left;">Name</th><th style="text-align:left;">Type</th><th style="text-align:left;">Default value</th></tr></thead><tbody><tr><td style="text-align:left;"><code>pose</code></td><td style="text-align:left;"><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></td><td style="text-align:left;"><code>undefined</code></td></tr><tr><td style="text-align:left;"><code>factor</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;"><code>undefined</code></td></tr><tr><td style="text-align:left;"><code>minDistance</code></td><td style="text-align:left;"><code>number</code></td><td style="text-align:left;"><code>1e-3</code></td></tr></tbody></table><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/Controls_cameraTransitions.Pose.html"><code>Pose</code></a></p><h4 id="defined-in-7" tabindex="-1">Defined in <a class="header-anchor" href="#defined-in-7" aria-label="Permalink to &quot;Defined in&quot;">​</a></h4><p><a href="https://github.com/LinkunGao/copper3d_visualisation/blob/467d39e/src/Controls/cameraTransitions.ts#L326" target="_blank" rel="noreferrer">src/Controls/cameraTransitions.ts:326</a></p>',90),s=[n];function i(d,l,c,h,u,m){return t(),a("div",null,s)}const b=e(r,[["render",i]]);export{f as __pageData,b as default};
